/**
 * Untitled UI icons (John's choice), drawn with react-native-svg from shapes
 * generated by scripts/sync-icons.mjs. 24-unit grid, 2-unit round stroke.
 *
 * Sized with Dynamic Type up to the same 2× cap as chrome text, so an icon
 * never outgrows its label. Decorative to VoiceOver: the control carries the
 * label.
 */

import { useWindowDimensions } from "react-native";
import Svg, { Path } from "react-native-svg";

import { usePalette } from "../design/tokens";
import { ICON_SHAPES, type IconName } from "./icons.generated";
import { ON_PICTURE } from "../design/palette";

export type { IconName } from "./icons.generated";

export function Icon({
  name,
  size = 20,
  tone = "ink",
  filled = false,
  strokeWidth = 2,
  maxScale = 2,
  color: given,
}: {
  name: IconName;
  size?: number;
  /** "white" stays white in both appearances: a glyph over a picture or the forest (the day's verse, DR-16). */
  tone?: "ink" | "muted" | "accent" | "paper" | "white";
  /** Solid shape, e.g. a set bookmark. */
  filled?: boolean;
  strokeWidth?: number;
  maxScale?: number;
  /** A colour from design/ for a glyph on its own ground: an avatar's initial colour (components/pray/Avatar.tsx). */
  color?: string;
}) {
  const palette = usePalette();
  const { fontScale } = useWindowDimensions();
  const px = Math.round(size * Math.min(Math.max(fontScale, 1), maxScale));
  const color =
    given ??
    (tone === "white" ? ON_PICTURE.text : tone === "muted" ? palette.mutedInk : tone === "accent" ? palette.accent : tone === "paper" ? palette.paper : palette.ink);
  return (
    <Svg
      width={px}
      height={px}
      viewBox="0 0 24 24"
      fill={filled ? color : "none"}
      stroke={color}
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      accessible={false}
      importantForAccessibility="no-hide-descendants"
    >
      {ICON_SHAPES[name].map((shape, i) => (
        <Path key={i} d={shape.attrs.d} />
      ))}
    </Svg>
  );
}
